module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

    reg [9:0] sum;
    reg [2:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum       <= 10'd0;
            counter   <= 3'd0;
            valid_out <= 1'b0;
            data_out  <= 10'd0;
        end else begin
            if (valid_in) begin
                sum <= sum + data_in;
                counter <= counter + 1'b1;
            end

            if (counter == 3'd4) begin
                valid_out <= 1'b1;
                data_out  <= sum;
                sum       <= 10'd0;
                counter   <= 3'd0;
            end else begin
                valid_out <= 1'b0;
            end
        end
    end

endmodule

