        if (!rst_n) begin
            sum <= 10'b0;
            count <= 3'b0;
            valid_out <= 1'b0;
            data_out <= 10'b0;
        end else begin
            valid_out <= 1'b0; // Default reset valid_out
            if (valid_in) begin
                sum <= sum + data_in;
                count <= count + 1'b1;
                if (count == 3'b011) begin // After 4 valid inputs
                    valid_out <= 1'b1;
                    data_out <= sum + data_in; // Output accumulated sum
                    sum <= 10'b0; // Reset sum
                    count <= 3'b0; // Reset count
                end
            end
        end
    end

endmodule

