module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

    wire carry_0;

    // Instantiate the first 8-bit adder
    adder_8bit adder_lower (
        .a(a[7:0]),
        .b(b[7:0]),
        .Cin(Cin),
        .y(y[7:0]),
        .Co(carry_0)
    );

    // Instantiate the second 8-bit adder
    adder_8bit adder_upper (
        .a(a[15:8]),
        .b(b[15:8]),
        .Cin(carry_0),
        .y(y[15:8]),
        .Co(Co)
    );

endmodule

module adder_8bit (
    input wire [7:0] a,
    input wire [7:0] b,
    input wire Cin,
    output wire [7:0] y,
    output wire Co
);

    wire [7:0] p; // Propagate signals (a XOR b)
    wire [7:0] g; // Generate signals (a AND b)
    wire [7:0] c; // Carry signals

    assign p = a ^ b;
    assign g = a & b;

    // Compute carries
    assign c[0] = Cin;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & c[1]);
    assign c[3] = g[2] | (p[2] & c[2]);
    assign c[4] = g[3] | (p[3] & c[3]);
    assign c[5] = g[4] | (p[4] & c[4]);
    assign c[6] = g[5] | (p[5] & c[5]);
    assign c[7] = g[6] | (p[6] & c[6]);

    // Compute sum and carry-out
    assign y = p ^ c[7:0];
    assign Co = g[7] | (p[7] & c[7]);

endmodule

