module adder_8bit (
    input wire [7:0] a,
    input wire [7:0] b,
    input wire Cin,
    output wire [7:0] y,
    output wire Co
);

    wire [7:0] carry;

    // Bit 0 addition
    assign {carry[0], y[0]} = a[0] + b[0] + Cin;

    // Bit 1 addition
    assign {carry[1], y[1]} = a[1] + b[1] + carry[0];

    // Bit 2 addition
    assign {carry[2], y[2]} = a[2] + b[2] + carry[1];

    // Bit 3 addition
    assign {carry[3], y[3]} = a[3] + b[3] + carry[2];

    // Bit 4 addition
    assign {carry[4], y[4]} = a[4] + b[4] + carry[3];

    // Bit 5 addition
    assign {carry[5], y[5]} = a[5] + b[5] + carry[4];

    // Bit 6 addition
    assign {carry[6], y[6]} = a[6] + b[6] + carry[5];

    // Bit 7 addition
    assign {Co, y[7]} = a[7] + b[7] + carry[6];

endmodule

