module cla_16bit(A, B, Cin, S, Cout);
    input [16:1] A;
    input [16:1] B;
    input Cin;
    output [16:1] S;
    output Cout;

    wire [16:1] P; // Propagate
    wire [16:1] G; // Generate
    wire [16:0] C; // Carry

    assign C[1] = Cin;

    // Generate and propagate signals
    genvar i;
    generate
        for (i = 1; i <= 16; i = i + 1) begin
            assign P[i] = A[i] ^ B[i];
            assign G[i] = A[i] & B[i];
        end
    endgenerate

    // Carry computation
    generate
        for (i = 2; i <= 16; i = i + 1) begin
            assign C[i] = G[i-1] | (P[i-1] & C[i-1]);
        end
    endgenerate
    assign Cout = G[16] | (P[16] & C[16]);

    // Sum computation
    generate
        for (i = 1; i <= 16; i = i + 1) begin
            assign S[i] = P[i] ^ C[i];
        end
    endgenerate

endmodule

