    assign G = {A & B, 1'b0}; // Generate generate signals

    assign C[0] = Cin;

    genvar i;
    generate
        for (i = 1; i < 17; i = i + 1) begin : carry_generate
            assign C[i] = G[i-1] | (P[i-1] & C[i-1]);
        end
    endgenerate

    assign S = P[16:1] ^ C[15:0]; // Compute sum
    assign Cout = C[16];          // Carry-out

endmodule

