module cla_16bit(A, B, Cin, S, Cout);
    input [16:1] A;
    input [16:1] B;
    input Cin;
    output [16:1] S;
    output Cout;

    wire [16:0] carry;
    wire [16:1] P, G;

    assign carry[0] = Cin;

    // Compute propagate and generate signals
    genvar i;
    generate
        for (i = 1; i <= 16; i = i + 1) begin
            assign P[i] = A[i] ^ B[i]; // Propagate
            assign G[i] = A[i] & B[i]; // Generate
        end
    endgenerate

    // Compute carry signals
    generate
        for (i = 1; i <= 16; i = i + 1) begin
            assign carry[i] = G[i] | (P[i] & carry[i-1]);
        end
    endgenerate

    // Compute sum signals
    generate
        for (i = 1; i <= 16; i = i + 1) begin
            assign S[i] = P[i] ^ carry[i-1];
        end
    endgenerate

    assign Cout = carry[16];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    // Internal registers for pipelining
    reg [DATA_WIDTH-1:0] stage_adda [0:DATA_WIDTH/STG_WIDTH-1];
    reg [DATA_WIDTH-1:0] stage_addb [0:DATA_WIDTH/STG_WIDTH-1];
    reg [STG_WIDTH:0] stage_sum [0:DATA_WIDTH/STG_WIDTH-1];
    reg stage_en [0:DATA_WIDTH/STG_WIDTH-1];

    // Output register
    reg [DATA_WIDTH:0] final_result;

    integer i;

    // Reset and pipeline initialization
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < DATA_WIDTH/STG_WIDTH; i = i + 1) begin
                stage_adda[i] <= 0;
                stage_addb[i] <= 0;
                stage_sum[i] <= 0;
                stage_en[i] <= 0;
            end
            final_result <= 0;
            o_en <= 0;
        end else begin
            // Pipeline stages
            for (i = 0; i < DATA_WIDTH/STG_WIDTH; i = i + 1) begin
                if (i == 0) begin
                    stage_adda[i] <= adda[STG_WIDTH-1:0];
                    stage_addb[i] <= addb[STG_WIDTH-1:0];
                    stage_sum[i] <= adda[STG_WIDTH-1:0] + addb[STG_WIDTH-1:0];
                    stage_en[i] <= i_en;
                end else begin
                    stage_adda[i] <= stage_adda[i-1];
                    stage_addb[i] <= stage_addb[i-1];
                    stage_sum[i] <= stage_sum[i-1] + stage_adda[i-1] + stage_addb[i-1];
                    stage_en[i] <= stage_en[i-1];
                end
            end

            // Final result
            final_result <= {stage_sum[DATA_WIDTH/STG_WIDTH-1], stage_sum[DATA_WIDTH/STG_WIDTH-2]};
            o_en <= stage_en[DATA_WIDTH/STG_WIDTH-1];
        end
    end

    assign result = final_result;

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    // Internal signals and registers
    reg [DATA_WIDTH-1:0] stage_adda [0:STG_WIDTH-1];
    reg [DATA_WIDTH-1:0] stage_addb [0:STG_WIDTH-1];
    reg [DATA_WIDTH:0] stage_result [0:STG_WIDTH-1];
    reg stage_en [0:STG_WIDTH-1];
    integer i;

    // Pipeline registers initialization and reset logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_en <= 1'b0;
            for (i = 0; i < STG_WIDTH; i = i + 1) begin
                stage_adda[i] <= {DATA_WIDTH{1'b0}};
                stage_addb[i] <= {DATA_WIDTH{1'b0}};
                stage_result[i] <= {DATA_WIDTH+1{1'b0}};
                stage_en[i] <= 1'b0;
            end
        end else begin
            // Pipeline stages operation
            stage_en[0] <= i_en;
            stage_adda[0] <= adda;
            stage_addb[0] <= addb;
            stage_result[0] <= {1'b0, adda} + {1'b0, addb};

            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                stage_en[i] <= stage_en[i-1];
                stage_adda[i] <= stage_adda[i-1];
                stage_addb[i] <= stage_addb[i-1];
                stage_result[i] <= stage_result[i-1];
            end

            // Output stage
            o_en <= stage_en[STG_WIDTH-1];
        end
    end

    assign result = stage_result[STG_WIDTH-1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    // Internal signals for pipeline stages
    reg [DATA_WIDTH-1:0] stage_adda [0:(DATA_WIDTH/STG_WIDTH)-1];
    reg [DATA_WIDTH-1:0] stage_addb [0:(DATA_WIDTH/STG_WIDTH)-1];
    reg [DATA_WIDTH/STG_WIDTH:0] carry_pipeline;
    reg [DATA_WIDTH/STG_WIDTH-1:0] enable_pipeline;
    reg [STG_WIDTH:0] partial_sum [0:(DATA_WIDTH/STG_WIDTH)-1];

    // Final result register
    reg [DATA_WIDTH:0] final_result;

    integer i;

    // Pipeline initialization and reset logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < (DATA_WIDTH/STG_WIDTH); i = i + 1) begin
                stage_adda[i] <= 0;
                stage_addb[i] <= 0;
                partial_sum[i] <= 0;
                enable_pipeline[i] <= 0;
            end
            carry_pipeline <= 0;
            o_en <= 0;
            final_result <= 0;
        end else begin
            // Pipeline enable and data propagation
            if (i_en) begin
                stage_adda[0] <= adda[STG_WIDTH-1:0];
                stage_addb[0] <= addb[STG_WIDTH-1:0];
                enable_pipeline[0] <= i_en;
                carry_pipeline[0] <= 0;

                for (i = 1; i < (DATA_WIDTH/STG_WIDTH); i = i + 1) begin
                    stage_adda[i] <= adda[i*STG_WIDTH +: STG_WIDTH];
                    stage_addb[i] <= addb[i*STG_WIDTH +: STG_WIDTH];
                    enable_pipeline[i] <= enable_pipeline[i-1];
                    carry_pipeline[i] <= carry_pipeline[i-1];
                end
            end else begin
                for (i = 0; i < (DATA_WIDTH/STG_WIDTH); i = i + 1) begin
                    enable_pipeline[i] <= enable_pipeline[i];
                    carry_pipeline[i] <= carry_pipeline[i];
                end
            end

            // Partial sum calculation and carry propagation
            for (i = 0; i < (DATA_WIDTH/STG_WIDTH); i = i + 1) begin
                {carry_pipeline[i+1], partial_sum[i]} <= stage_adda[i] + stage_addb[i] + carry_pipeline[i];
            end

            // Final result assignment
            final_result <= {carry_pipeline[DATA_WIDTH/STG_WIDTH], partial_sum[(DATA_WIDTH/STG_WIDTH)-1]};
            o_en <= enable_pipeline[(DATA_WIDTH/STG_WIDTH)-1];
        end
    end

    assign result = final_result;

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    // Internal signals
    reg [DATA_WIDTH-1:0] reg_adda [STG_WIDTH-1:0];
    reg [DATA_WIDTH-1:0] reg_addb [STG_WIDTH-1:0];
    reg [DATA_WIDTH:0] reg_result [STG_WIDTH-1:0];
    reg [STG_WIDTH-1:0] reg_enable;

    integer i;

    // Pipeline reset logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < STG_WIDTH; i = i + 1) begin
                reg_adda[i] <= 0;
                reg_addb[i] <= 0;
                reg_result[i] <= 0;
                reg_enable[i] <= 0;
            end
            o_en <= 0;
        end else begin
            // Pipeline stage 0
            reg_adda[0] <= adda;
            reg_addb[0] <= addb;
            reg_result[0] <= adda + addb;
            reg_enable[0] <= i_en;

            // Pipeline propagation
            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                reg_adda[i] <= reg_adda[i-1];
                reg_addb[i] <= reg_addb[i-1];
                reg_result[i] <= reg_result[i-1];
                reg_enable[i] <= reg_enable[i-1];
            end

            // Output logic
            o_en <= reg_enable[STG_WIDTH-1];
        end
    end

    // Final result assignment
    assign result = reg_result[STG_WIDTH-1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    // Internal registers
    reg [DATA_WIDTH-1:0] pipeline_a [0:STG_WIDTH-1];
    reg [DATA_WIDTH-1:0] pipeline_b [0:STG_WIDTH-1];
    reg [DATA_WIDTH:0] pipeline_sum [0:STG_WIDTH-1];
    reg pipeline_en [0:STG_WIDTH-1];

    integer i;

    // Pipeline initialization/reset
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < STG_WIDTH; i = i + 1) begin
                pipeline_a[i] <= 0;
                pipeline_b[i] <= 0;
                pipeline_sum[i] <= 0;
                pipeline_en[i] <= 0;
            end
            o_en <= 0;
        end else begin
            // Stage 0: Load inputs
            pipeline_a[0] <= adda;
            pipeline_b[0] <= addb;
            pipeline_en[0] <= i_en;

            // Propagate through pipeline stages
            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                pipeline_a[i] <= pipeline_a[i-1];
                pipeline_b[i] <= pipeline_b[i-1];
                pipeline_en[i] <= pipeline_en[i-1];
                pipeline_sum[i] <= pipeline_a[i-1] + pipeline_b[i-1];
            end

            // Final stage output
            pipeline_sum[STG_WIDTH-1] <= pipeline_a[STG_WIDTH-1] + pipeline_b[STG_WIDTH-1];
            o_en <= pipeline_en[STG_WIDTH-1];
        end
    end

    // Assign the final result
    assign result = pipeline_sum[STG_WIDTH-1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    // Declare pipeline registers
    reg [DATA_WIDTH-1:0] stage_adda [0:(DATA_WIDTH/STG_WIDTH)-1];
    reg [DATA_WIDTH-1:0] stage_addb [0:(DATA_WIDTH/STG_WIDTH)-1];
    reg [STG_WIDTH:0] stage_sum [0:(DATA_WIDTH/STG_WIDTH)-1];
    reg stage_en [0:(DATA_WIDTH/STG_WIDTH)];
    reg [DATA_WIDTH:0] final_result;

    integer i;

    // Initialize pipeline stages
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all pipeline registers
            for (i = 0; i < (DATA_WIDTH/STG_WIDTH); i = i + 1) begin
                stage_adda[i] <= 0;
                stage_addb[i] <= 0;
                stage_sum[i] <= 0;
                stage_en[i] <= 0;
            end
            stage_en[DATA_WIDTH/STG_WIDTH] <= 0;
            final_result <= 0;
            o_en <= 0;
        end else begin
            // Propagate enable signal through pipeline stages
            stage_en[0] <= i_en;
            for (i = 1; i <= (DATA_WIDTH/STG_WIDTH); i = i + 1) begin
                stage_en[i] <= stage_en[i-1];
            end

            // Load input to first stage
            if (i_en) begin
                stage_adda[0] <= adda[STG_WIDTH-1:0];
                stage_addb[0] <= addb[STG_WIDTH-1:0];
            end

            // Perform addition and propagate through pipeline stages
            for (i = 0; i < (DATA_WIDTH/STG_WIDTH)-1; i = i + 1) begin
                if (stage_en[i]) begin
                    stage_sum[i] <= stage_adda[i] + stage_addb[i] + stage_sum[i][STG_WIDTH];
                    stage_adda[i+1] <= adda[(i+1)*STG_WIDTH +: STG_WIDTH];
                    stage_addb[i+1] <= addb[(i+1)*STG_WIDTH +: STG_WIDTH];
                end
            end

            // Handle final stage
            if (stage_en[DATA_WIDTH/STG_WIDTH-1]) begin
                final_result <= {stage_sum[DATA_WIDTH/STG_WIDTH-1][STG_WIDTH], stage_sum[DATA_WIDTH/STG_WIDTH-1][STG_WIDTH-1:0]};
                o_en <= stage_en[DATA_WIDTH/STG_WIDTH-1];
            end else begin
                o_en <= 0;
            end
        end
    end

    // Output result
    assign result = final_result;

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

// Internal registers for pipeline stages
reg [DATA_WIDTH-1:0] adda_reg [0:3];
reg [DATA_WIDTH-1:0] addb_reg [0:3];
reg [DATA_WIDTH:0] sum_reg [0:3];
reg en_reg [0:3];

// Pipeline stage 0: Input capture
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        adda_reg[0] <= 0;
        addb_reg[0] <= 0;
        en_reg[0] <= 0;
    end else if (i_en) begin
        adda_reg[0] <= adda;
        addb_reg[0] <= addb;
        en_reg[0] <= 1;
    end else begin
        en_reg[0] <= 0;
    end
end

// Pipeline stages for addition and carry propagation
genvar i;
generate
    for (i = 1; i < 4; i = i + 1) begin : pipeline_stages
        always @(posedge clk or negedge rst_n) begin
            if (!rst_n) begin
                adda_reg[i] <= 0;
                addb_reg[i] <= 0;
                sum_reg[i] <= 0;
                en_reg[i] <= 0;
            end else begin
                adda_reg[i] <= adda_reg[i-1];
                addb_reg[i] <= addb_reg[i-1];
                sum_reg[i] <= sum_reg[i-1] + {1'b0, adda_reg[i-1]} + {1'b0, addb_reg[i-1]};
                en_reg[i] <= en_reg[i-1];
            end
        end
    end
endgenerate

// Final stage: Output generation
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg[0] <= 0;
        o_en <= 0;
    end else begin
        sum_reg[0] <= {1'b0, adda_reg[3]} + {1'b0, addb_reg[3]};
        o_en <= en_reg[3];
    end
end

assign result = sum_reg[0];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    // Internal registers for pipelining
    reg [DATA_WIDTH-1:0] adda_reg [0:DATA_WIDTH/STG_WIDTH-1];
    reg [DATA_WIDTH-1:0] addb_reg [0:DATA_WIDTH/STG_WIDTH-1];
    reg [DATA_WIDTH:0] sum_reg [0:DATA_WIDTH/STG_WIDTH-1];
    reg carry_reg [0:DATA_WIDTH/STG_WIDTH-1];
    reg stage_en [0:DATA_WIDTH/STG_WIDTH-1];

    integer i;

    // Pipeline stages initialization and reset logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < DATA_WIDTH/STG_WIDTH; i = i + 1) begin
                adda_reg[i] <= 0;
                addb_reg[i] <= 0;
                sum_reg[i] <= 0;
                carry_reg[i] <= 0;
                stage_en[i] <= 0;
            end
            o_en <= 0;
        end else begin
            // Pipeline enable propagation and addition logic
            if (i_en) begin
                adda_reg[0] <= adda[STG_WIDTH-1:0];
                addb_reg[0] <= addb[STG_WIDTH-1:0];
                sum_reg[0] <= adda[STG_WIDTH-1:0] + addb[STG_WIDTH-1:0];
                carry_reg[0] <= (adda[STG_WIDTH-1:0] + addb[STG_WIDTH-1:0]) >> STG_WIDTH;
                stage_en[0] <= i_en;
            end

            for (i = 1; i < DATA_WIDTH/STG_WIDTH; i = i + 1) begin
                if (stage_en[i-1]) begin
                    adda_reg[i] <= adda[(i+1)*STG_WIDTH-1:i*STG_WIDTH];
                    addb_reg[i] <= addb[(i+1)*STG_WIDTH-1:i*STG_WIDTH];
                    sum_reg[i] <= adda_reg[i] + addb_reg[i] + carry_reg[i-1];
                    carry_reg[i] <= (adda_reg[i] + addb_reg[i] + carry_reg[i-1]) >> STG_WIDTH;
                    stage_en[i] <= stage_en[i-1];
                end
            end

            // Final output stage
            if (stage_en[DATA_WIDTH/STG_WIDTH-1]) begin
                o_en <= 1;
            end else begin
                o_en <= 0;
            end
        end
    end

    // Concatenate all pipeline results to form the final result
    assign result = {carry_reg[DATA_WIDTH/STG_WIDTH-1], sum_reg[DATA_WIDTH/STG_WIDTH-1]};

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    // Number of pipeline stages calculated as DATA_WIDTH / STG_WIDTH
    localparam NUM_STAGES = DATA_WIDTH / STG_WIDTH;

    // Pipeline registers for partial sums and carry
    reg [STG_WIDTH:0] sum_reg[NUM_STAGES-1:0];
    reg carry_reg[NUM_STAGES-1:0];
    reg enable_reg[NUM_STAGES:0];

    // Input registers for pipelining
    reg [DATA_WIDTH-1:0] adda_reg, addb_reg;

    integer i;

    // Pipeline initialization on reset
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < NUM_STAGES; i = i + 1) begin
                sum_reg[i] <= 0;
                carry_reg[i] <= 0;
            end
            enable_reg[0] <= 0;
            o_en <= 0;
        end else begin
            // Register the inputs and enable signal
            adda_reg <= adda;
            addb_reg <= addb;
            enable_reg[0] <= i_en;

            // Perform pipelined addition
            for (i = 0; i < NUM_STAGES; i = i + 1) begin
                if (i == 0) begin
                    {carry_reg[i], sum_reg[i]} <= adda_reg[STG_WIDTH-1:0] + addb_reg[STG_WIDTH-1:0];
                end else begin
                    {carry_reg[i], sum_reg[i]} <= adda_reg[i*STG_WIDTH +: STG_WIDTH] + addb_reg[i*STG_WIDTH +: STG_WIDTH] + carry_reg[i-1];
                end
                enable_reg[i+1] <= enable_reg[i];
            end

            // Output final result and enable
            result <= {carry_reg[NUM_STAGES-1], sum_reg[NUM_STAGES-1], sum_reg[NUM_STAGES-2]};
            o_en <= enable_reg[NUM_STAGES];
        end
    end

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    // Pipeline registers to store intermediate results
    reg [DATA_WIDTH:0] stage_sum[0:(DATA_WIDTH/STG_WIDTH)];
    reg carry[0:(DATA_WIDTH/STG_WIDTH)];
    reg stage_en[0:(DATA_WIDTH/STG_WIDTH)];
    integer i;

    // Reset all pipeline stages
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i <= (DATA_WIDTH/STG_WIDTH); i = i + 1) begin
                stage_sum[i] <= 0;
                carry[i] <= 0;
                stage_en[i] <= 0;
            end
            o_en <= 0;
        end else begin
            // Stage 0: Load inputs
            if (i_en) begin
                stage_sum[0] <= adda[STG_WIDTH-1:0] + addb[STG_WIDTH-1:0];
                carry[0] <= (adda[STG_WIDTH-1:0] + addb[STG_WIDTH-1:0]) >> STG_WIDTH;
                stage_en[0] <= 1;
            end else begin
                stage_en[0] <= 0;
            end

            // Propagate through pipeline stages
            for (i = 1; i <= (DATA_WIDTH/STG_WIDTH); i = i + 1) begin
                if (stage_en[i-1]) begin
                    stage_sum[i] <= stage_sum[i-1] + (adda[i*STG_WIDTH +: STG_WIDTH] + addb[i*STG_WIDTH +: STG_WIDTH]) + carry[i-1];
                    carry[i] <= (adda[i*STG_WIDTH +: STG_WIDTH] + addb[i*STG_WIDTH +: STG_WIDTH] + carry[i-1]) >> STG_WIDTH;
                    stage_en[i] <= 1;
                end else begin
                    stage_en[i] <= 0;
                end
            end

            // Final stage: Output result
            if (stage_en[DATA_WIDTH/STG_WIDTH]) begin
                o_en <= 1;
            end else begin
                o_en <= 0;
            end
        end
    end

    assign result = stage_sum[DATA_WIDTH/STG_WIDTH];

endmodule

module asyn_fifo#(
	parameter	WIDTH = 8,
	parameter 	DEPTH = 16
)(
	input 					wclk	, 
	input 					rclk	,   
	input 					wrstn	,
	input					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
	output wire [WIDTH-1:0]	rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);

// Dual-port RAM
reg [WIDTH-1:0] ram [DEPTH-1:0];
reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
reg [ADDR_WIDTH-1:0] waddr_gray, raddr_gray;
reg [ADDR_WIDTH-1:0] waddr_gray_sync1, waddr_gray_sync2;
reg [ADDR_WIDTH-1:0] raddr_gray_sync1, raddr_gray_sync2;
reg wfull_flag, rempty_flag;

assign wfull = wfull_flag;
assign rempty = rempty_flag;
assign rdata = ram[raddr_bin];

// Write Pointer Logic
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		waddr_bin <= 0;
		waddr_gray <= 0;
	end else if (winc && !wfull_flag) begin
		waddr_bin <= waddr_bin + 1;
		waddr_gray <= (waddr_bin + 1) ^ ((waddr_bin + 1) >> 1);
	end
end

// Read Pointer Logic
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		raddr_bin <= 0;
		raddr_gray <= 0;
	end else if (rinc && !rempty_flag) begin
		raddr_bin <= raddr_bin + 1;
		raddr_gray <= (raddr_bin + 1) ^ ((raddr_bin + 1) >> 1);
	end
end

// RAM Write Logic
always @(posedge wclk) begin
	if (winc && !wfull_flag) begin
		ram[waddr_bin] <= wdata;
	end
end

// Synchronize Write Pointer into Read Clock Domain
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		waddr_gray_sync1 <= 0;
		waddr_gray_sync2 <= 0;
	end else begin
		waddr_gray_sync1 <= waddr_gray;
		waddr_gray_sync2 <= waddr_gray_sync1;
	end
end

// Synchronize Read Pointer into Write Clock Domain
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		raddr_gray_sync1 <= 0;
		raddr_gray_sync2 <= 0;
	end else begin
		raddr_gray_sync1 <= raddr_gray;
		raddr_gray_sync2 <= raddr_gray_sync1;
	end
end

// Full Detection
always @(*) begin
	wfull_flag = (waddr_gray == {~raddr_gray_sync2[ADDR_WIDTH-1:ADDR_WIDTH-2], raddr_gray_sync2[ADDR_WIDTH-3:0]});
end

// Empty Detection
always @(*) begin
	rempty_flag = (raddr_gray == waddr_gray_sync2);
end

endmodule

module asyn_fifo#(
	parameter	WIDTH = 8,
	parameter 	DEPTH = 16
)(
	input 					wclk	, 
	input 					rclk	,   
	input 					wrstn	,
	input					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
