);

parameter ADDR_WIDTH = $clog2(DEPTH);

// Dual-port RAM
reg [WIDTH-1:0] ram [DEPTH-1:0];
reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;

// Write Pointer and Write Synchronizer
reg [ADDR_WIDTH:0] wptr_bin, wptr_gray, wptr_sync1, wptr_sync2;
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		wptr_bin <= 0;
		wptr_gray <= 0;
	end else if (winc && !wfull) begin
		wptr_bin <= wptr_bin + 1;
		wptr_gray <= (wptr_bin >> 1) ^ wptr_bin;
	end
end

always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		wptr_sync1 <= 0;
		wptr_sync2 <= 0;
	end else begin
		wptr_sync1 <= wptr_gray;
		wptr_sync2 <= wptr_sync1;
	end
end

// Read Pointer and Read Synchronizer
reg [ADDR_WIDTH:0] rptr_bin, rptr_gray, rptr_sync1, rptr_sync2;
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		rptr_bin <= 0;
		rptr_gray <= 0;
	end else if (rinc && !rempty) begin
		rptr_bin <= rptr_bin + 1;
		rptr_gray <= (rptr_bin >> 1) ^ rptr_bin;
	end
end

always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		rptr_sync1 <= 0;
		rptr_sync2 <= 0;
	end else begin
		rptr_sync1 <= rptr_gray;
		rptr_sync2 <= rptr_sync1;
	end
end

// Write Operation
always @(posedge wclk) begin
	if (winc && !wfull) begin
		ram[wptr_bin[ADDR_WIDTH-1:0]] <= wdata;
	end
end

// Read Operation
assign rdata = ram[rptr_bin[ADDR_WIDTH-1:0]];

// Empty and Full Flags
assign rempty = (rptr_gray == wptr_sync2);
assign wfull = (wptr_gray[ADDR_WIDTH] != rptr_sync2[ADDR_WIDTH]) &&
			   (wptr_gray[ADDR_WIDTH-1:0] == rptr_sync2[ADDR_WIDTH-1:0]);

endmodule

