// State encoding
localparam S0 = 3'b000,
           S1 = 3'b001,
           S2 = 3'b010,
           S3 = 3'b011,
           S4 = 3'b100,
           S5 = 3'b101;

// Sequential logic: State transition
always @(posedge CLK or posedge RST) begin
    if (RST)
        state <= S0;
    else
        state <= next_state;
end

// Combinational logic: Next state and output logic
always @(*) begin
    // Default values
    next_state = state;
    MATCH = 0;

    case (state)
        S0: begin
            if (IN) next_state = S1;
        end

        S1: begin
            if (!IN) next_state = S2;
        end

        S2: begin
            if (!IN) next_state = S3;
            else next_state = S1; // Restart sequence detection
        end

        S3: begin
            if (IN) next_state = S4;
            else next_state = S0; // Restart sequence detection
        end

        S4: begin
            if (IN) next_state = S5;
            else next_state = S2; // Restart sequence detection
        end

        S5: begin
            MATCH = 1; // Sequence detected
            if (IN) next_state = S1;
            else next_state = S2; // Restart sequence detection
        end
    endcase
end

endmodule

