module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] multiplicand, product;
   reg [7:0] multiplier;
   reg [4:0] ctr;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         multiplicand <= {{8{a[7]}}, a}; // Sign extend a
         multiplier <= b;
         product <= 16'b0;
         ctr <= 5'b0;
         rdy <= 0;
      end else begin
         if (ctr < 8) begin
            case ({multiplier[ctr], (ctr > 0 ? multiplier[ctr - 1] : 0)})
               2'b01: product <= product + multiplicand;
               2'b10: product <= product - multiplicand;
               default: product <= product;
            endcase
            multiplicand <= multiplicand << 1;
            ctr <= ctr + 1;
         end else begin
            p <= product;
            rdy <= 1;
         end
      end
   end
endmodule

