   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] multiplicand, multiplier;
   reg [4:0] ctr; // Counter (5 bits to count up to 16 cycles)
   reg [15:0] partial_product;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 16'd0;
         rdy <= 0;
         multiplicand <= {{8{a[7]}}, a}; // Sign-extend multiplicand
         multiplier <= {{8{b[7]}}, b};   // Sign-extend multiplier
         ctr <= 5'd0;
         partial_product <= 16'd0;
      end else begin
         if (ctr < 16) begin
            case ({multiplier[ctr], multiplier[ctr+1]})
               2'b01: partial_product <= partial_product + multiplicand; // Add multiplicand
               2'b10: partial_product <= partial_product - multiplicand; // Subtract multiplicand
               default: partial_product <= partial_product; // No operation
            endcase
            multiplicand <= multiplicand << 1; // Shift multiplicand
            ctr <= ctr + 1; // Increment counter
         end else begin
            p <= partial_product; // Store final product
            rdy <= 1; // Set ready signal
         end
      end
   end
endmodule

