         ctr <= 0;
         multiplicand <= {{8{a[7]}}, a};
         multiplier <= {{8{b[7]}}, b};
         temp_p <= 17'b0;
      end else begin
         if (ctr < 8) begin
            case ({multiplier[ctr + 1], multiplier[ctr]})
               2'b01: temp_p <= temp_p + multiplicand;
               2'b10: temp_p <= temp_p - multiplicand;
               default: temp_p <= temp_p;
            endcase
            multiplicand <= multiplicand << 1;
            ctr <= ctr + 1;
         end else begin
            rdy <= 1;
            p <= temp_p[15:0];
         end
      end
   end
endmodule

