module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] multiplicand, multiplier;
   reg [4:0] ctr; // 5-bit counter for 16 cycles
   reg [2:0] booth_bits;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         multiplicand <= {{8{a[7]}}, a}; // Sign extend a
         multiplier <= {{8{b[7]}}, b};   // Sign extend b
         p <= 16'd0;
         ctr <= 5'd0;
         rdy <= 1'b0;
         booth_bits <= 3'b0;
      end else if (!rdy) begin
         booth_bits <= {multiplier[ctr+1], multiplier[ctr], multiplier[ctr-1]};
         case (booth_bits)
            3'b001, 3'b010: p <= p + multiplicand;
            3'b011: p <= p + (multiplicand << 1);
            3'b100: p <= p - (multiplicand << 1);
            3'b101, 3'b110: p <= p - multiplicand;
            default: p <= p;
         endcase
         multiplicand <= multiplicand << 1;
         ctr <= ctr + 1;
         if (ctr == 5'd15) rdy <= 1'b1;
      end
   end
endmodule

