module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Pipeline registers
reg [N-1:0] partial_sum_1;
reg [N-1:0] partial_sum_2;

integer i;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		partial_sum_1 <= 0;
		partial_sum_2 <= 0;
		mul_out <= 0;
	end else begin
		// Stage 1: Partial product generation and accumulation
		partial_sum_1 <= 0;
		for (i = 0; i < size; i = i + 1) begin
			if (mul_b[i])
				partial_sum_1 <= partial_sum_1 + (mul_a << i);
		end

		// Stage 2: Pipeline final sum computation
		partial_sum_2 <= partial_sum_1;
		mul_out <= partial_sum_2;
	end
end

endmodule

