module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    // State encoding
    reg [1:0] state;
    parameter IDLE = 2'b00, RISE = 2'b01, FALL = 2'b10, PULSE = 2'b11;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    data_out <= 1'b0;
                    if (data_in == 1'b1) 
                        state <= RISE;
                end
                RISE: begin
                    data_out <= 1'b0;
                    if (data_in == 1'b0) 
                        state <= FALL;
                    else if (data_in == 1'b1)
                        state <= RISE;
                    else 
                        state <= IDLE;
                end
                FALL: begin
                    data_out <= 1'b0;
                    if (data_in == 1'b0) 
                        state <= PULSE;
                    else 
                        state <= IDLE;
                end
                PULSE: begin
                    data_out <= 1'b1;
                    state <= IDLE;
                end
                default: begin
                    state <= IDLE;
                    data_out <= 1'b0;
                end
            endcase
        end
    end
endmodule

