module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Registers in clk_a domain
	reg [3:0] data_reg_a;
	reg       data_en_reg_a;

	// Registers in clk_b domain
	reg       en_clap_one;
	reg       en_clap_two;
	reg [3:0] data_reg_b;

	// Synchronize data_in and data_en in clk_a domain
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg_a    <= 4'b0;
			data_en_reg_a <= 1'b0;
		end else if (data_en) begin
			data_reg_a    <= data_in;
			data_en_reg_a <= data_en;
		end
	end

	// Synchronize enable signal across clk_b domain
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			en_clap_one <= 1'b0;
			en_clap_two <= 1'b0;
		end else begin
			en_clap_one <= data_en_reg_a;
			en_clap_two <= en_clap_one;
		end
	end

	// Update dataout in clk_b domain based on enable synchronization
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout     <= 4'b0;
			data_reg_b  <= 4'b0;
		end else if (en_clap_two) begin
			data_reg_b  <= data_reg_a;
			dataout     <= data_reg_b;
		end
	end

endmodule

