    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] r_reg;
    reg zero_reg, carry_reg, negative_reg, overflow_reg;
    reg flag_reg;

    assign r = r_reg;
    assign zero = zero_reg;
    assign carry = carry_reg;
    assign negative = negative_reg;
    assign overflow = overflow_reg;
    assign flag = flag_reg;

    always @(*) begin
        r_reg = 32'bz;
        zero_reg = 1'b0;
        carry_reg = 1'b0;
        negative_reg = 1'b0;
        overflow_reg = 1'b0;
        flag_reg = 1'bz;

        case (aluc)
            ADD: begin
                r_reg = a + b;
                carry_reg = (a[31] & b[31]) | ((a[31] | b[31]) & ~r_reg[31]);
                overflow_reg = (~a[31] & ~b[31] & r_reg[31]) | (a[31] & b[31] & ~r_reg[31]);
            end
            ADDU: begin
                r_reg = a + b;
                carry_reg = (a + b) > 32'hFFFFFFFF;
            end
            SUB: begin
                r_reg = a - b;
                carry_reg = (~a[31] & b[31]) | ((~a[31] | b[31]) & r_reg[31]);
                overflow_reg = (a[31] & ~b[31] & ~r_reg[31]) | (~a[31] & b[31] & r_reg[31]);
            end
            SUBU: begin
                r_reg = a - b;
                carry_reg = a < b;
            end
            AND: r_reg = a & b;
            OR: r_reg = a | b;
            XOR: r_reg = a ^ b;
            NOR: r_reg = ~(a | b);
            SLT: begin
                r_reg = (a < b) ? 32'b1 : 32'b0;
                flag_reg = (a < b) ? 1'b1 : 1'bz;
            end
            SLTU: begin
                r_reg = (a < b) ? 32'b1 : 32'b0;
                flag_reg = (a < b) ? 1'b1 : 1'bz;
            end
            SLL: r_reg = b << a[4:0];
