module div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

    reg [15:0] quotient;
    reg [15:0] remainder;
    reg [7:0] temp;

    integer i;

    always @(*) begin
        quotient = 16'b0;
        remainder = 16'b0;

        for (i = 15; i >= 0; i = i - 1) begin
            remainder = {remainder[14:0], A[i]}; // Shift left and concatenate the next dividend bit
            temp = remainder[15:8];             // Extract the higher 8 bits of the remainder

            if (temp >= B) begin
                quotient[i] = 1'b1;             // Set quotient bit to 1 if temp >= B
                remainder[15:8] = temp - B;     // Update the remainder
            end 
            else begin
                quotient[i] = 1'b0;             // Set quotient bit to 0 if temp < B
            end
        end
    end

    assign result = quotient;
    assign odd = remainder;

endmodule

