module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output wire[7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;

	reg [1:0] state, next_state;
	reg [7:0] cnt;

	assign clock = cnt;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			state <= idle;
			cnt <= 8'd0;
		end else begin
			state <= next_state;
			if (state == s3_green && pass_request && cnt > 8'd10) begin
				cnt <= cnt - 8'd1;
			end else if (cnt > 0) begin
				cnt <= cnt - 8'd1;
			end
		end
	end

	always @(*) begin
		case (state)
			idle: begin
				red = 1'b0;
