	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			red <= 1'b0;
			yellow <= 1'b0;
			green <= 1'b0;
		end else begin
			case (state)
				idle: begin
					red <= 1'b0;
					yellow <= 1'b0;
					green <= 1'b0;
